<?php
namespace App\Policies; use App\Domain\Tenancy\TenantContext; use App\Models\{CommissionRuleVersion,User}; final class CommissionRuleVersionPolicy{public function viewAny(User$u):bool{/* UI audit 2026-09-27: was any active member */return$u->memberships()->where('status','ACTIVE')->exists()&&($u->hasPermission('commission.manage'));}public function view(User$u,CommissionRuleVersion$m):bool{return$m->tenant_id===app(TenantContext::class)->id()&&$this->viewAny($u);}public function create(User$u):bool{return$this->viewAny($u);}public function update(User$u,CommissionRuleVersion$m):bool{return$this->view($u,$m)&&$m->status==='DRAFT';}public function delete(User$u,CommissionRuleVersion$m):bool{return false;}}
